attempts.query:
PREFIX oncologia: <https://w3id.org/rastro/oncologia#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT (COUNT(DISTINCT ?d) AS ?n) WHERE {
  ?tr a oncologia:Trial ; oncologia:condition ?c ; oncologia:testsDrug ?d .
  ?c oncologia:within ?m . ?m rdfs:label "Multiple Myeloma"@en .
}
